import React,{useState} from 'react';
import {View,Modal,Pressable,ScrollView,Platform} from 'react-native';
import {AppText,Button,Field} from './ui';
import {useTheme,fontStyle} from './theme';
import {Icon} from './brand';
import locations from './locations.json';
import {phtParts,deadlineISO} from './date-time.cjs';
export function Sheet({visible,title,onClose,children}){const {colors}=useTheme();return <Modal visible={visible} transparent animationType="fade" onRequestClose={onClose}><View style={{flex:1,backgroundColor:'#0008',justifyContent:'center',padding:16}}><View accessibilityViewIsModal style={{backgroundColor:colors.surface,borderRadius:24,maxHeight:'90%',width:'100%',maxWidth:600,alignSelf:'center',padding:20,gap:14}}><AppText variant="heading" accessibilityRole="header">{title}</AppText><ScrollView keyboardShouldPersistTaps="handled" contentContainerStyle={{gap:12,paddingBottom:8}}>{children}</ScrollView><Button title="Done" onPress={onClose}/></View></View></Modal>;}
export function Select({label,value,options,onChange}){const [open,setOpen]=useState(false);return <View style={{gap:6}}><AppText>{label}</AppText><Button secondary title={(options.find(o=>o.value===value)?.label||value)+'  ▾'} accessibilityLabel={label+', '+(options.find(o=>o.value===value)?.label||value)} accessibilityState={{expanded:open}} onPress={()=>setOpen(true)}/><Sheet visible={open} title={label} onClose={()=>setOpen(false)}>{options.map(o=><Button key={o.value} title={o.label} secondary={value!==o.value} accessibilityState={{selected:value===o.value}} onPress={()=>{onChange(o.value);setOpen(false);}}/>)}</Sheet></View>;}
const clean=s=>s.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
export const locationByCode=Object.fromEntries(locations.map(l=>[l.code,l]));
export const locationLabel=code=>{const l=locationByCode[code];return l?`${l.name}, ${l.province||l.region}`:code;};
export function LocationSelect({label,value=[],onChange,multiple=false}){
 const [open,setOpen]=useState(false),[search,setSearch]=useState('');const {colors}=useTheme();
 const terms=clean(search).trim().split(/\s+/).filter(Boolean);
 const results=locations.filter(l=>terms.every(t=>clean(`${l.name} ${l.province} ${l.region}`).includes(t)));
 function choose(code){onChange(multiple?(value.includes(code)?value.filter(c=>c!==code):value.length<20?[...value,code]:value):[code]);if(!multiple)setOpen(false);}
 return <View style={{gap:8}}><AppText>{label}</AppText><Button secondary title={value.length?(multiple?`${value.length} selected · Change areas`:locationLabel(value[0])):'Search cities or municipalities  ▾'} accessibilityState={{expanded:open}} onPress={()=>{setSearch('');setOpen(true);}}/>
 {multiple&&!!value.length&&<View style={{flexDirection:'row',flexWrap:'wrap',gap:8}}>{value.map(code=><Pressable key={code} accessibilityRole="button" accessibilityLabel={'Remove '+locationLabel(code)} onPress={()=>onChange(value.filter(c=>c!==code))} style={{minHeight:48,padding:10,backgroundColor:colors.surface,borderColor:colors.border,borderWidth:1,borderRadius:14,justifyContent:'center',maxWidth:'100%'}}><AppText style={{fontSize:14}}>{locationLabel(code)} ×</AppText></Pressable>)}</View>}
 <Sheet visible={open} title={label} onClose={()=>setOpen(false)}><Field autoFocus label="Search by name, province or region" value={search} onChangeText={setSearch} placeholder="For example: Quezon, Laguna" maxLength={80}/>
 {multiple&&<><AppText variant="muted">Select up to 20 areas. Any selected area can match.</AppText><Button secondary title="Clear selections" onPress={()=>onChange([])}/></>}
 {!results.length&&<AppText>No matching city or municipality.</AppText>}
 {results.slice(0,40).map(l=><Pressable key={l.code} aria-checked={value.includes(l.code)} accessibilityRole={multiple?'checkbox':'radio'} accessibilityState={{checked:value.includes(l.code),disabled:multiple&&value.length>=20&&!value.includes(l.code)}} disabled={multiple&&value.length>=20&&!value.includes(l.code)} onPress={()=>choose(l.code)} style={{padding:12,minHeight:60,gap:4,borderRadius:12,borderWidth:1,borderColor:value.includes(l.code)?colors.accent:colors.border,backgroundColor:value.includes(l.code)?colors.background:colors.surface}}><AppText style={{fontWeight:'600'}}>{value.includes(l.code)?'✓  ':''}{l.name}</AppText><AppText variant="muted" style={{fontSize:14}}>{[l.province,l.region].filter(Boolean).join(' · ')} · {l.kind}</AppText></Pressable>)}
 {results.length>40&&<AppText variant="muted">Showing 40 of {results.length}. Type more to narrow your search.</AppText>}
 <AppText variant="muted" style={{fontSize:12}}>Source: Philippine Statistics Authority, PSGC, 30 September 2026. Names and city/municipality records only; no GPS tracking.</AppText></Sheet></View>;
}
export function DeadlinePicker({value,onChange}){const {colors,isDark}=useTheme();const parts=value?value.split(' '):['',''];
 function update(date,time){onChange(`${date} ${time}`.trim());}
 async function native(mode){const {DateTimePickerAndroid}=require('@react-native-community/datetimepicker');const initial=deadlineISO(value)||new Date(Date.now()+3600000).toISOString();DateTimePickerAndroid.open({value:new Date(initial),mode,is24Hour:false,timeZoneName:'Asia/Manila',minimumDate:mode==='date'?new Date():undefined,maximumDate:mode==='date'?new Date(Date.now()+30*86400000):undefined,onChange:(event,date)=>{if(event.type==='set'&&date){const p=phtParts(date);update(mode==='date'?p.date:(parts[0]||p.date),mode==='time'?p.time:(parts[1]||p.time));}},display:mode==='date'?'calendar':'clock'});}
 const webStyle={fontFamily:fontStyle.fontFamily,fontSize:18,padding:14,minHeight:52,borderRadius:12,border:`1px solid ${colors.border}`,backgroundColor:colors.input,color:colors.text,colorScheme:isDark?'dark':'light',width:'100%',boxSizing:'border-box'};
 const today=phtParts(new Date()).date;
 return <View style={{gap:10}}><AppText>Collect by · Philippines time</AppText><View style={{flexDirection:'row',gap:8,flexWrap:'wrap'}}>{[0,1].map(n=><Button key={n} secondary title={n?'Tomorrow':'Today'} onPress={()=>update(phtParts(new Date(Date.now()+n*86400000)).date,parts[1]||'18:00')}/>)}</View>
 {Platform.OS==='web'?<><label style={{...fontStyle,fontSize:16,lineHeight:'25px',display:'flex',flexDirection:'column',gap:6,color:colors.text}}>Collection date<input aria-label="Collection date" type="date" min={today} max={phtParts(new Date(Date.now()+30*86400000)).date} value={parts[0]||''} onInput={e=>update(e.currentTarget.value,parts[1]||'18:00')} style={webStyle}/></label><label style={{...fontStyle,fontSize:16,lineHeight:'25px',display:'flex',flexDirection:'column',gap:6,color:colors.text}}>Collection time<input aria-label="Collection time" type="time" value={parts[1]||''} onInput={e=>update(parts[0]||today,e.currentTarget.value)} style={webStyle}/></label></>:<><Button secondary title={parts[0]||'Choose collection date'} onPress={()=>native('date')}/><Button secondary title={parts[1]||'Choose collection time'} onPress={()=>native('time')}/></>}
 {!!deadlineISO(value)&&<AppText style={{color:colors.accent}}>Collect by {new Date(deadlineISO(value)).toLocaleString('en-PH',{timeZone:'Asia/Manila',month:'long',day:'numeric',year:'numeric',hour:'numeric',minute:'2-digit'})} PHT</AppText>}
 <AppText variant="muted">Choose a future time within the next 30 days.</AppText></View>;
}
